import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.jupiter.api.Test;

class OrderServiceExpireStaleTest {

    // 2026-10-31 02:00 Warsaw (CET, UTC+1) is 2026-10-31 01:00 UTC.
    private final Clock clock = Clock.fixed(Instant.parse("2026-10-31T01:00:00Z"), ZoneOffset.UTC);

    private final OrderRepository orders = new OrderRepository();
    private final OrderService service = new OrderService(orders, clock);

    private String placed(String id, String placedAt, String status) {
        Order order = new Order(id, "c-1", Money.pln(1000), Instant.parse(placedAt));
        order.changeStatus(status);
        orders.save(order);
        return id;
    }

    @Test
    void cancelsPlacedOrdersOlderThanThirtyDaysAndLeavesTheRest() {
        // Warsaw dates: 2026-09-30 is 31 days before 2026-10-31; 2026-10-01 is exactly 30 days before.
        placed("old-placed", "2026-09-29T20:00:00Z", "PLACED");
        placed("boundary-placed", "2026-09-30T20:00:00Z", "PLACED");
        placed("recent-placed", "2026-10-01T10:00:00Z", "PLACED");
        placed("old-confirmed", "2026-09-01T10:00:00Z", "CONFIRMED");
        placed("old-cancelled", "2026-09-01T10:00:00Z", "CANCELLED");

        int cancelled = service.expireStale();

        assertEquals(1, cancelled);
        assertEquals("CANCELLED", orders.get("old-placed").status());
        assertEquals("PLACED", orders.get("boundary-placed").status());
        assertEquals("PLACED", orders.get("recent-placed").status());
        assertEquals("CONFIRMED", orders.get("old-confirmed").status());
        assertEquals("CANCELLED", orders.get("old-cancelled").status());
    }

    @Test
    void usesTheWarsawCalendarDayNotUtc() {
        // 2026-10-02 23:30 UTC is already 2026-10-03 Warsaw; 31 days before 2026-10-31 would be 2026-09-30.
        // Warsaw date 2026-09-30 is more than 30 days before 2026-10-31, so it is stale.
        placed("warsaw-stale", "2026-09-30T00:30:00Z", "PLACED");
        // 2026-09-30 23:30 UTC is 2026-10-01 Warsaw, exactly 30 days before: not stale.
        placed("warsaw-boundary", "2026-09-30T23:30:00Z", "PLACED");

        assertEquals(1, service.expireStale());
        assertEquals("CANCELLED", orders.get("warsaw-stale").status());
        assertEquals("PLACED", orders.get("warsaw-boundary").status());
    }

    @Test
    void returnsZeroWhenNothingIsStale() {
        assertEquals(0, service.expireStale());
    }
}
}

