        assertEquals(1, cancelled);
        assertEquals("CANCELLED", orders.get("day-31-placed").status());
        assertEquals("PLACED", orders.get("day-30-placed").status());
        assertEquals("CONFIRMED", orders.get("old-confirmed").status());
        assertEquals("CANCELLED", orders.get("old-cancelled").status());
    }

    @Test
    void decidesByTheWarsawCalendarDayNotUtc() {
        // 2026-09-30 00:30 UTC is 2026-09-30 in Warsaw: 31 days old, stale.
        placed("warsaw-stale", "2026-09-30T00:30:00Z", "PLACED");
        // 2026-09-30 23:30 UTC is 2026-10-01 in Warsaw: 30 days old, not stale.
        // (Judged by UTC it would be September 30 and stale, so this checks the zone.)
        placed("warsaw-boundary", "2026-09-30T23:30:00Z", "PLACED");

        assertEquals(1, service.expireStale());
        assertEquals("CANCELLED", orders.get("warsaw-stale").status());
        assertEquals("PLACED", orders.get("warsaw-boundary").status());
    }

    @Test
    void returnsZeroWhenNothingIsStale() {
        placed("recent", "2026-10-30T10:00:00Z", "PLACED");

        assertEquals(0, service.expireStale());
        assertEquals("PLACED", orders.get("recent").status());
    }
